using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Aspose.Pdf;
using Aspose.Pdf.Annotations;
using Aspose.Pdf.Devices;
using Aspose.Pdf.Forms;
using Aspose.Pdf.Text;
using Tachylite.Core.Models;

namespace Tachylite.Core.Services;

public class PdfService : IPdfService
{
    // Generated by OpenCode's Big Pickle: shared raster background resolution.
    private const int BackgroundResolutionDpi = 110;

    // Generated by OpenCode's Big Pickle: tolerance used when ignoring text fragments that belong to fields.
    private const double FieldBoundsTolerance = 2.0;

    // Generated by OpenCode's Big Pickle: carries a field together with the widget rectangle and a stable key.
    private sealed record FieldPlacement(Field Field, Aspose.Pdf.Rectangle? Bounds, string WidgetKey);

    // Changed by OpenCode's Big Pickle: opens the PDF once, builds all page models, then mutates the
    // same in-memory document for background rendering. Callbacks let the UI appear progressively.
    public PdfDocumentModel ConstructPdfDocumentModel(
        byte[] documentData,
        string documentName,
        PdfPageBackgroundImageType backgroundImageType,
        Action<PdfDocumentModel>? onDocumentReady = null,
        Action<PdfPageModel>? onPageReady = null)
    {
        using Document document = Document.Open(documentData);

        // Generated by OpenCode's Big Pickle: widget-aware field collection fixes missing text box fields.
        FieldPlacement[][] pageFields = CollectFieldPlacements(document);

        // Generated by OpenCode's Big Pickle: field names are captured before the render document is mutated.
        string[] fieldNames = [.. document.Form.Fields
            .Where(IsExtractableField)
            .Select(field => field.FullName ?? field.Name ?? string.Empty)
            .Where(name => name.Length > 0)
            .Distinct(StringComparer.Ordinal)];

        PdfPageModel[] pages = new PdfPageModel[document.PageCount];
        foreach (Page page in document.Pages)
        {
            int pageIndex = page.Number - 1;

            // BackgroundImage is filled in below after the page model has been extracted.
            pages[pageIndex] = ConstructPdfPageModel(
                page,
                pageFields[pageIndex],
                backgroundImageType,
                []);
        }

        PdfDocumentModel result = new()
        {
            Name = documentName,
            Pages = pages
        };

        onDocumentReady?.Invoke(result);

        // Changed by OpenCode's Big Pickle: removes form fields/widgets only after all models exist.
        foreach (string fieldName in fieldNames)
            document.RemoveFormField(fieldName);

        foreach (Page page in document.Pages)
        {
            // Generated by OpenCode's Big Pickle: removes widget appearances not covered by AcroForm fields.
            foreach (WidgetAnnotation widget in page.Annotations.OfType<WidgetAnnotation>().ToArray())
                page.Annotations.Delete(widget);

            BlankOverlayText(page);
        }

        foreach (Page page in document.Pages)
        {
            int pageIndex = page.Number - 1;
            pages[pageIndex].BackgroundImage = RenderPageBackground(page, backgroundImageType);
            onPageReady?.Invoke(pages[pageIndex]);
        }

        return result;
    }

    // Changed by OpenCode's Big Pickle: public overload now accepts the pre-rendered background image.
    public PdfPageModel ConstructPdfPageModel(
        Page page,
        Field[] fields,
        PdfPageBackgroundImageType backgroundImageType,
        byte[] backgroundImage)
    {
        // Generated by OpenCode's Big Pickle: adapts the public Field[] signature to widget-aware field placements.
        return ConstructPdfPageModel(
            page,
            [.. fields.Select((field, index) => new FieldPlacement(
                field,
                field.Rect,
                $"{field.FullName ?? field.Name ?? string.Empty}#{index}"))],
            backgroundImageType,
            backgroundImage);
    }

    // Generated by OpenCode's Big Pickle: internal page builder that preserves widget bounds for each field.
    private PdfPageModel ConstructPdfPageModel(
        Page page,
        FieldPlacement[] fields,
        PdfPageBackgroundImageType backgroundImageType,
        byte[] backgroundImage)
    {
        List<PdfTextElementModel> textElements = [];
        List<PdfImageElementModel> imageElements = [];
        List<PdfFormFieldElementModel> fieldElements = [];

        // Changed by OpenCode's Big Pickle: creates field models using each widget's bounds.
        foreach (FieldPlacement placement in fields)
        {
            fieldElements.Add(ConstructPdfFormFieldElementModel(
                placement.Field,
                placement.Bounds,
                placement.WidgetKey,
                page.Number));
        }

        // Generated by OpenCode's Big Pickle: used to keep text that belongs to a field out of the overlay layer.
        System.Drawing.Rectangle[] fieldBounds = [.. fieldElements
            .Where(f => f.Bounds.Width > 0 && f.Bounds.Height > 0)
            .Select(f => f.Bounds)];

        TextFragmentAbsorber textAbsorber = new();
        page.Accept(textAbsorber);

        foreach (TextFragment textFragment in textAbsorber.TextFragments)
        {
            // Changed by OpenCode's Big Pickle: kept intentionally. Rotated text remains in the
            // background image instead of becoming an awkward rotated overlay control.
            if (textFragment.TextState.Rotation != 0) continue;

            if (string.IsNullOrWhiteSpace(textFragment.Text)) continue;
            if (textFragment.Rectangle is not { } rect) continue;

            // Changed by OpenCode's Big Pickle: normalizes inverted PDF rectangles before using them
            // as System.Drawing bounds; MMRPG contains field/text rectangles with LLY > URY.
            System.Drawing.Rectangle textBounds =
                NormalizeRectangle(rect)?.ToRect() ?? rect.ToRect();

            // Generated by OpenCode's Big Pickle: skips field value text that would otherwise be
            // duplicated by the interactive text box/checkbox/choice controls.
            if (IsInsideAnyField(textBounds, fieldBounds)) continue;

            textElements.Add(ConstructPdfTextElementModel(textFragment));
        }

        // Changed by OpenCode's Big Pickle: removed the old dead reverse-removal loop over
        // textAbsorber.TextFragments; extraction and WritePdfBytes now use the same filters.

        return new PdfPageModel()
        {
            PageNumber = page.Number,
            Rotation = page.RotateDegrees,
            Dimensions = new PdfPageSizeModel(page.Width, page.Height),
            BackgroundImage = backgroundImage,
            BackgroundImageType = backgroundImageType,
            TextElements = [.. textElements],
            ImageElements = [.. imageElements],
            FormFieldElements = [.. fieldElements]
        };
    }

    // Changed by OpenCode's Big Pickle: font bytes from Font.Save() are only valid inside a converted
    // document, so they are no longer exported. Only custom fonts that cannot be resolved to a real
    // UI font are left in Aspose's rendered page background; standard fonts remain visible overlays.
    public PdfTextElementModel ConstructPdfTextElementModel(TextFragment textFragment)
    {
        double rotation = NormalizeRotation(textFragment.TextState.Rotation);

        string? fontName = GetFontName(textFragment);

        return new PdfTextElementModel()
        {
            TextContent = textFragment.Text,
            // Changed by OpenCode's Big Pickle: stores normalized bounds so inverted PDF rectangles
            // do not become zero/negative-height Avalonia overlay bounds.
            Bounds = NormalizeRectangle(textFragment.Rectangle)?.ToRect(),
            Rotation = rotation,
            FontName = fontName,
            RequiresRasterFont = RequiresRasterFont(textFragment),
            FontSize = textFragment.TextState.FontSize,
            ForegroundColor = textFragment.TextState.ForegroundColor?.ToRgb(),
            BackgroundColor = textFragment.TextState.BackgroundColor?.ToRgb()
        };
    }

    // Changed by OpenCode's Big Pickle: accepts explicit widget bounds and normalizes inverted
    // PDF rectangles before creating field models, fixing missing MMRPG Powers text fields.
    public PdfFormFieldElementModel ConstructPdfFormFieldElementModel(
        Field field,
        Aspose.Pdf.Rectangle? bounds = null,
        string? widgetKey = null,
        int pageNumber = 0)
    {
        // Changed by OpenCode's Big Pickle: bounds fallback chain now normalizes every source.
        Aspose.Pdf.Rectangle? rect = NormalizeRectangle(bounds);

        if (rect is null) rect = NormalizeRectangle(field.Rect);
        if (rect is null)
        {
            try { rect = NormalizeRectangle(field.GetRectangle(false)); }
            catch { rect = null; }
        }

        var fieldName = field.FullName ?? field.Name ?? string.Empty;
        string widgetId = widgetKey ?? fieldName;
        var boundsRect = rect?.ToRect() ?? new System.Drawing.Rectangle();  

        return field switch
        {
            TextBoxField textBox => new TextBoxFieldModel
            {
                FieldName = fieldName,
                WidgetKey = widgetId,
                Bounds = boundsRect,
                PageNumber = pageNumber > 0 ? pageNumber : GetPageNumber(field.Page, field.PageIndex),
                MaxLength = textBox.MaxLen > 0 ? textBox.MaxLen : null,
                IsMultiline = textBox.IsMultiline,
                IsScrollable = textBox.Scrollable,
                Value = textBox.Value ?? string.Empty,
                DefaultValue = textBox.DefaultValue,
                FontSize = textBox.DefaultAppearance is { } appearance && appearance.FontSize > 0
                ? appearance.FontSize
                : null,
                FontName = textBox.DefaultAppearance?.FontName,
                Color = textBox.Color?.ToRgb() ?? default
            },

            CheckboxField checkBox => new CheckBoxFieldModel
            {
                FieldName = fieldName,
                WidgetKey = widgetId,
                Bounds = boundsRect,
                PageNumber = pageNumber > 0 ? pageNumber : GetPageNumber(field.Page, field.PageIndex),
                IsChecked = checkBox.IsChecked
            },

            ComboBoxField comboBox => new ComboBoxFieldModel
            {
                FieldName = fieldName,
                WidgetKey = widgetId,
                Bounds = boundsRect,
                PageNumber = pageNumber > 0 ? pageNumber : GetPageNumber(field.Page, field.PageIndex),
                IsMultiselect = comboBox.IsMultiSelect,
                DefaultValue = comboBox.DefaultValue,
                Options = [.. comboBox.Options.Select(o => o.Name ?? o.Value)],
                SelectedIndices = [.. comboBox.SelectedIndices]
            },

            ListBoxField listBox => new ListBoxFieldModel
            {
                FieldName = fieldName,
                WidgetKey = widgetId,
                Bounds = boundsRect,
                PageNumber = pageNumber > 0 ? pageNumber : GetPageNumber(field.Page, field.PageIndex),
                IsMultiselect = listBox.IsMultiSelect,
                DefaultValue = listBox.DefaultValue,
                Options = [.. listBox.Options.Select(o => o.Name ?? o.Value)],
                SelectedIndices = [.. listBox.SelectedIndices]
            },

            RadioButtonField radioButton => new RadioButtonFieldModel
            {
                FieldName = fieldName,
                WidgetKey = widgetId,
                Bounds = boundsRect,
                PageNumber = pageNumber > 0 ? pageNumber : GetPageNumber(field.Page, field.PageIndex),
                NoToggleOff = radioButton.NoToggleToOff,
                IsMultiselect = radioButton.IsMultiSelect,
                DefaultValue = radioButton.DefaultValue,
                Options = [.. radioButton.Options.Select(o => o.Name ?? o.Value)],
                SelectedIndices = [.. radioButton.SelectedIndices]
            },

            _ => throw new ArgumentException(
                $"Unsupported field type '{field.Type}' on field '{fieldName}'.",
                nameof(field))
        };
    }

    // Changed by OpenCode's Big Pickle: mirrors the extraction filters so positional text write-back
    // stays aligned with the same fragments that were extracted.
    public byte[] WritePdfBytes(byte[] documentData, PdfDocumentModel documentModel)
    {
        // Generated by OpenCode Big Pickle
        static bool Close(double left, double right) => Math.Abs(left - right) < 0.5;

        static bool SameColor(System.Drawing.Color? left, System.Drawing.Color? right) =>
            left is null
                ? right is null
                : right is not null && left.Value.ToArgb() == right.Value.ToArgb();

        static void SyncOptions(ChoiceField field, string?[] options, int[] selectedIndices)
        {
            string[] wanted = [.. options.Where(o => o is not null).Select(o => o!)];
            string[] existing = [.. field.Options
                .Select(o => o.Name ?? o.Value)
                .Where(v => v is not null)
                .Select(v => v!)];

            if (!existing.SequenceEqual(wanted, StringComparer.Ordinal))
            {
                foreach (string option in existing) field.DeleteOption(option);
                foreach (string option in wanted) field.AddOption(option);
            }

            string[] values = [.. selectedIndices
                .Where(i => i >= 0 && i < wanted.Length)
                .Select(i => wanted[i])];

            if (!field.SelectedValues.SequenceEqual(values, StringComparer.Ordinal))
                field.SelectedValues = values;
        }

        // Reused field names produce one model per widget. Separate field dictionaries match by
        // bounds/page; one field with several widgets has a union Rect, so fall back to the edited model.
        static PdfFormFieldElementModel? SelectFieldModel(
            Field field,
            IReadOnlyList<PdfFormFieldElementModel> models)
        {
            if (models.Count == 0) return null;
            if (models.Count == 1) return models[0];

            Aspose.Pdf.Rectangle? fieldRect = NormalizeRectangle(field.Rect);
            List<PdfFormFieldElementModel> boundsMatches = [];

            if (fieldRect is not null)
            {
                foreach (PdfFormFieldElementModel model in models)
                {
                    Aspose.Pdf.Rectangle? modelRect =
                        NormalizeRectangle(Aspose.Pdf.Rectangle.FromRect(model.Bounds));

                    if (modelRect is not null && fieldRect.NearEquals(modelRect, FieldBoundsTolerance))
                        boundsMatches.Add(model);
                }
            }

            if (boundsMatches.Count == 1) return boundsMatches[0];

            if (boundsMatches.Count > 1)
            {
                int fieldPage = GetPageNumber(field.Page, field.PageIndex);
                PdfFormFieldElementModel? pageMatch = boundsMatches
                    .FirstOrDefault(model => model.PageNumber == fieldPage);

                if (pageMatch is not null) return pageMatch;
            }

            foreach (PdfFormFieldElementModel model in models)
            {
                bool wasEdited = (field, model) switch
                {
                    (TextBoxField textBox, TextBoxFieldModel textBoxModel) =>
                        !string.Equals(textBox.Value, textBoxModel.Value, StringComparison.Ordinal),
                    (CheckboxField checkBox, CheckBoxFieldModel checkBoxModel) =>
                        checkBox.IsChecked != checkBoxModel.IsChecked,
                    _ => false
                };

                if (wasEdited) return model;
            }

            return models[^1];
        }

        using Document document = Document.Open(documentData);

        if (!string.Equals(document.Info.Title, documentModel.Name, StringComparison.Ordinal))
            document.Info.Title = documentModel.Name;

        Dictionary<string, List<PdfFormFieldElementModel>> fieldModels = [];
        foreach (PdfPageModel pageModel in documentModel.Pages)
        {
            foreach (PdfFormFieldElementModel fieldModel in pageModel.FormFieldElements ?? [])
            {
                if (!fieldModels.TryGetValue(fieldModel.FieldName, out List<PdfFormFieldElementModel>? models))
                {
                    models = [];
                    fieldModels[fieldModel.FieldName] = models;
                }

                models.Add(fieldModel);
            }
        }

        foreach (PdfPageModel pageModel in documentModel.Pages)
        {
            if (pageModel.PageNumber < 1 || pageModel.PageNumber > document.PageCount)
                continue;

            Page page = document.Pages[pageModel.PageNumber];

            if (!Close(page.RotateDegrees, pageModel.Rotation))
                page.RotateDegrees = pageModel.Rotation;

            if (!Close(page.Width, pageModel.Dimensions.Width) ||
                !Close(page.Height, pageModel.Dimensions.Height))
                page.SetPageSize(pageModel.Dimensions.Width, pageModel.Dimensions.Height);

            TextFragmentAbsorber absorber = new();
            page.Accept(absorber);

             // Changed by OpenCode's Big Pickle: mirrors normalized field bounds used during extraction.
            System.Drawing.Rectangle[] fieldBounds = [.. (pageModel.FormFieldElements ?? [])
                .Where(f => f.Bounds.Width > 0 && f.Bounds.Height > 0)
                .Select(f => NormalizeRectangle(Aspose.Pdf.Rectangle.FromRect(f.Bounds))?.ToRect() ?? f.Bounds)];

            int elementIndex = 0;
            foreach (TextFragment fragment in absorber.TextFragments)
            {
                // Changed by OpenCode's Big Pickle: keeps rotated text out of overlay write-back,
                // matching the intentional decision to leave angled text in the background.
                if (fragment.TextState.Rotation != 0) continue;

                // Generated by OpenCode's Big Pickle: skips empty and field-owned fragments.
                if (string.IsNullOrWhiteSpace(fragment.Text)) continue;
                if (fragment.Rectangle is not { } rect) continue;

                // Changed by OpenCode's Big Pickle: normalizes inverted fragment rectangles before
                // comparing them against field bounds.
                System.Drawing.Rectangle fragmentBounds =
                    NormalizeRectangle(rect)?.ToRect() ?? rect.ToRect();

                if (IsInsideAnyField(fragmentBounds, fieldBounds)) continue;

                if (elementIndex >= pageModel.TextElements.Length)
                    break;

                PdfTextElementModel textModel = pageModel.TextElements[elementIndex++];

                // Changed by OpenCode's Big Pickle: uses normalized bounds for comparison.
                Aspose.Pdf.Rectangle? originalBounds = NormalizeRectangle(fragment.Rectangle);

                if (textModel.TextContent is string text &&
                    !string.Equals(fragment.Text, text, StringComparison.Ordinal))
                    fragment.Text = text;

                if (textModel.Bounds is System.Drawing.Rectangle bounds)
                {
                    Aspose.Pdf.Rectangle wanted = Aspose.Pdf.Rectangle.FromRect(bounds);
                    if (originalBounds is null || !originalBounds.NearEquals(wanted, 0.5))
                        fragment.Position = new Position(wanted.LLX, wanted.LLY);
                }

                // Changed by OpenCode's Big Pickle: FontName is no longer written back. The model may
                // hold a decoded/base font name, and replacing the PDF font name would corrupt text that
                // Aspose continues to render with its original embedded font program.

                if (textModel.FontSize is double fontSize && !Close(fragment.TextState.FontSize, fontSize))
                    fragment.TextState.FontSize = (float)fontSize;

                if (textModel.ForegroundColor is System.Drawing.Color foreground &&
                    !SameColor(fragment.TextState.ForegroundColor?.ToRgb(), foreground))
                    fragment.TextState.ForegroundColor = Aspose.Pdf.Color.FromRgb(foreground);

                if (textModel.BackgroundColor is System.Drawing.Color background &&
                    !SameColor(fragment.TextState.BackgroundColor?.ToRgb(), background))
                    fragment.TextState.BackgroundColor = Aspose.Pdf.Color.FromRgb(background);

                if (Math.Abs(fragment.TextState.Rotation - textModel.Rotation) > 0.5)
                    fragment.TextState.Rotation = textModel.Rotation;
            }

            foreach (PdfImageElementModel imageModel in pageModel.ImageElements)
            {
                if (imageModel.ImageData is { Length: > 0 } imageData)
                    page.AddImage(imageData, Aspose.Pdf.Rectangle.FromRect(imageModel.Bounds));
            }
        }

        foreach (Field field in document.Form.Fields)
        {
            string fieldName = field.FullName ?? field.Name ?? string.Empty;
            if (!fieldModels.TryGetValue(fieldName, out List<PdfFormFieldElementModel>? models))
                continue;

            PdfFormFieldElementModel? fieldModel = SelectFieldModel(field, models);
            if (fieldModel is null) continue;

            // Field.Rect is intentionally left alone. For reused field names it is the union of every
            // widget, and rewriting it from one widget's bounds would move the other widgets.

            switch (field, fieldModel)
            {
                case (TextBoxField textBox, TextBoxFieldModel textBoxModel):
                    if (!string.Equals(textBox.Value, textBoxModel.Value, StringComparison.Ordinal))
                        textBox.Value = textBoxModel.Value;
                    if (textBox.MaxLen != (textBoxModel.MaxLength ?? 0))
                        textBox.MaxLen = textBoxModel.MaxLength ?? 0;
                    if (textBox.IsMultiline != textBoxModel.IsMultiline)
                        textBox.Multiline = textBoxModel.IsMultiline;
                    if (textBox.Scrollable != textBoxModel.IsScrollable)
                        textBox.Scrollable = textBoxModel.IsScrollable;
                    if (!SameColor(textBox.Color?.ToRgb(), textBoxModel.Color))
                        textBox.Color = Aspose.Pdf.Color.FromRgb(textBoxModel.Color);
                    break;

                case (CheckboxField checkBox, CheckBoxFieldModel checkBoxModel):
                    if (checkBox.IsChecked != checkBoxModel.IsChecked)
                        checkBox.IsChecked = checkBoxModel.IsChecked;
                    break;

                case (ComboBoxField comboBox, ComboBoxFieldModel comboBoxModel):
                    if (comboBox.MultiSelect != comboBoxModel.IsMultiselect)
                        comboBox.MultiSelect = comboBoxModel.IsMultiselect;
                    SyncOptions(comboBox, comboBoxModel.Options, comboBoxModel.SelectedIndices);
                    break;

                case (ListBoxField listBox, ListBoxFieldModel listBoxModel):
                    if (listBox.MultiSelect != listBoxModel.IsMultiselect)
                        listBox.MultiSelect = listBoxModel.IsMultiselect;
                    SyncOptions(listBox, listBoxModel.Options, listBoxModel.SelectedIndices);
                    break;

                case (RadioButtonField radioButton, RadioButtonFieldModel radioButtonModel):
                    if (radioButton.NoToggleToOff != radioButtonModel.NoToggleOff)
                        radioButton.NoToggleToOff = radioButtonModel.NoToggleOff;
                    if (radioButton.MultiSelect != radioButtonModel.IsMultiselect)
                        radioButton.MultiSelect = radioButtonModel.IsMultiselect;
                    SyncOptions(radioButton, radioButtonModel.Options, radioButtonModel.SelectedIndices);
                    break;
            }
        }

        return document.ToArray();
    }

    // Generated by OpenCode's Big Pickle: uses the actual widget annotations on each page. Some PDFs
    // reuse one field name on several pages; document.Form.Fields then exposes a single field with a
    // union Rect, which produced oversized/misplaced controls.
    private static FieldPlacement[][] CollectFieldPlacements(Document document)
    {
        List<FieldPlacement>[] placementsByPage = new List<FieldPlacement>[document.PageCount];
        for (int i = 0; i < placementsByPage.Length; i++)
            placementsByPage[i] = [];

        Dictionary<string, Field> fieldsByName = new(StringComparer.Ordinal);
        HashSet<string> fieldsWithWidgets = new(StringComparer.Ordinal);
        Dictionary<string, int> widgetCounts = new(StringComparer.Ordinal);

        foreach (Field field in document.Form.Fields)
        {
            if (!IsExtractableField(field)) continue;

            string fieldName = field.FullName ?? field.Name ?? string.Empty;
            if (fieldName.Length > 0) fieldsByName.TryAdd(fieldName, field);
        }

        // Widget annotations carry the real per-page rectangle even when Field.GetWidgetEnumerator()
        // is empty and Field.Rect is the union of every widget with the same name.
        foreach (Page page in document.Pages)
        {
            foreach (WidgetAnnotation widget in page.Annotations.OfType<WidgetAnnotation>())
            {
                string fieldName = widget.FullName ?? widget.Name ?? string.Empty;
                if (!fieldsByName.TryGetValue(fieldName, out Field? field)) continue;

                fieldsWithWidgets.Add(fieldName);
                if (IsHiddenWidget(widget)) continue;

                int pageNumber = GetPageNumber(widget.Page, widget.PageIndex);
                if (pageNumber < 1 || pageNumber > placementsByPage.Length) continue;

                widgetCounts.TryGetValue(fieldName, out int widgetIndex);
                widgetCounts[fieldName] = widgetIndex + 1;

                Aspose.Pdf.Rectangle? bounds = NormalizeRectangle(widget.Rect);
                placementsByPage[pageNumber - 1].Add(
                    new FieldPlacement(field, bounds, $"{fieldName}#{widgetIndex}"));
            }
        }

        // Fallback for extractable fields with no matching widget annotation at all.
        foreach (Field field in document.Form.Fields)
        {
            if (!IsExtractableField(field)) continue;

            string fieldName = field.FullName ?? field.Name ?? string.Empty;
            if (fieldName.Length == 0 || fieldsWithWidgets.Contains(fieldName)) continue;

            int fallbackPage = GetPageNumber(field.Page, field.PageIndex);
            if (fallbackPage < 1 || fallbackPage > placementsByPage.Length) continue;

            widgetCounts.TryGetValue(fieldName, out int widgetIndex);
            widgetCounts[fieldName] = widgetIndex + 1;

            placementsByPage[fallbackPage - 1].Add(new FieldPlacement(
                field,
                NormalizeRectangle(field.Rect),
                $"{fieldName}#{widgetIndex}"));
        }

        FieldPlacement[][] result = new FieldPlacement[document.PageCount][];
        for (int i = 0; i < result.Length; i++)
            result[i] = [.. placementsByPage[i]];

        return result;
    }

    // Changed by OpenCode's Big Pickle: blanks text the editor can draw itself. Custom embedded/subset
    // fonts stay in the background because their subset bytes are not usable as real UI fonts.
    // Rotated fragments are also left in the background.
    private static void BlankOverlayText(Page page)
    {
        TextFragmentAbsorber absorber = new();
        page.Accept(absorber);

        foreach (TextFragment fragment in absorber.TextFragments)
        {
            if (fragment.TextState.Rotation != 0) continue;
            if (string.IsNullOrWhiteSpace(fragment.Text)) continue;
            if (RequiresRasterFont(fragment)) continue;

            try
            {
                fragment.Text = string.Empty;
            }
            catch
            {
                // Leave this fragment alone if Aspose cannot rewrite it.
            }
        }
    }

    // Changed by OpenCode's Big Pickle: uses raster rendering for both background modes because
    // SvgDevice does not faithfully render CMYK images with soft masks.
    private static byte[] RenderPageBackground(Page page, PdfPageBackgroundImageType backgroundImageType)
    {
        PngDevice imageDevice = new(new Resolution(BackgroundResolutionDpi));
        return imageDevice.Process(page);
    }

    // Generated by OpenCode's Big Pickle: centralizes which Aspose field types this editor supports.
    private static bool IsExtractableField(Field field) =>
        field.Type is FieldType.Text
            or FieldType.CheckBox
            or FieldType.ComboBox
            or FieldType.ListBox
            or FieldType.RadioButton;

    // Changed by OpenCode's Big Pickle: Aspose PageIndex is 1-based, so a widget whose Page cannot be
    // resolved must use it directly instead of adding one (which moved fields to the following page).
    private static int GetPageNumber(Page? page, int pageIndex) =>
        page is { Number: > 0 } ? page.Number : (pageIndex > 0 ? pageIndex : 1);

    // Generated by OpenCode's Big Pickle: hidden/no-view widgets must not become visible editor controls.
    private static bool IsHiddenWidget(WidgetAnnotation widget)
    {
        try
        {
            return widget.Flags.HasFlag(AnnotationFlags.Hidden) ||
                   widget.Flags.HasFlag(AnnotationFlags.NoView);
        }
        catch
        {
            return false;
        }
    }

    // Generated by OpenCode's Big Pickle: shares font-name selection between extraction and rendering.
    private static string? GetFontName(TextFragment fragment)
    {
        Aspose.Pdf.Text.Font? font = fragment.TextState.Font;

        string? fontName = fragment.TextState.FontName;
        if (string.IsNullOrWhiteSpace(fontName)) fontName = font?.DecodedFontName;
        if (string.IsNullOrWhiteSpace(fontName)) fontName = font?.FontName;
        if (string.IsNullOrWhiteSpace(fontName)) fontName = font?.BaseFont;

        return fontName;
    }

    // Changed by OpenCode's Big Pickle: only custom embedded/subset fonts need Aspose rendering.
    // Standard fonts can still be drawn as visible, selectable Avalonia overlays.
    private static bool RequiresRasterFont(TextFragment fragment) =>
        RequiresRasterFont(fragment.TextState.Font, GetFontName(fragment));

    private static bool RequiresRasterFont(Aspose.Pdf.Text.Font? font, string? fontName)
    {
        if (font is null || !(font.IsEmbedded || font.IsSubset)) return false;
        if (string.IsNullOrWhiteSpace(fontName)) return false;

        string name = StripPdfSubsetPrefix(fontName);

        return name.StartsWith("Armadura", StringComparison.OrdinalIgnoreCase) ||
               name.StartsWith("MyriadPro", StringComparison.OrdinalIgnoreCase) ||
               name.StartsWith("Myriad Pro", StringComparison.OrdinalIgnoreCase) ||
               name.StartsWith("Eurostile", StringComparison.OrdinalIgnoreCase) ||
               name.StartsWith("ESRI", StringComparison.OrdinalIgnoreCase) ||
               name.StartsWith("ITCSymbolStd", StringComparison.OrdinalIgnoreCase);
    }

    // Generated by OpenCode's Big Pickle: removes PDF subset prefixes such as "ABCDEF+".
    private static string StripPdfSubsetPrefix(string fontName)
    {
        int separator = fontName.IndexOf('+');
        return separator >= 0 && separator < fontName.Length - 1
            ? fontName[(separator + 1)..]
            : fontName;
    }

    // Changed by OpenCode's Big Pickle: accepts inverted rectangles by checking absolute width/height.
    private static bool HasArea(Aspose.Pdf.Rectangle? rect) =>
        rect is not null &&
        Math.Abs(rect.URX - rect.LLX) > 0.01 &&
        Math.Abs(rect.URY - rect.LLY) > 0.01;

    // Generated by OpenCode's Big Pickle: converts PDF rectangles with reversed coordinates into
    // LLX/LLY/URX/URY order so System.Drawing bounds are positive and fields are not skipped.
    private static Aspose.Pdf.Rectangle? NormalizeRectangle(Aspose.Pdf.Rectangle? rect)
    {
        if (!HasArea(rect)) return null;

        double left = Math.Min(rect!.LLX, rect.URX);
        double right = Math.Max(rect.LLX, rect.URX);
        double bottom = Math.Min(rect.LLY, rect.URY);
        double top = Math.Max(rect.LLY, rect.URY);

        return new Aspose.Pdf.Rectangle(left, bottom, right, top);
    }
    // Generated by OpenCode's Big Pickle: prevents field value text from becoming a duplicate overlay.
    private static bool IsInsideAnyField(
        System.Drawing.Rectangle bounds,
        System.Drawing.Rectangle[] fieldBounds)
    {
        foreach (System.Drawing.Rectangle field in fieldBounds)
        {
            if (bounds.X >= field.X - FieldBoundsTolerance &&
                bounds.Y >= field.Y - FieldBoundsTolerance &&
                bounds.Right <= field.Right + FieldBoundsTolerance &&
                bounds.Bottom <= field.Bottom + FieldBoundsTolerance)
                return true;
        }

        return false;
    }

    // Generated by OpenCode's Big Pickle: normalizes PDF rotation into the 0-360 range.
    private static double NormalizeRotation(double rotation)
    {
        double result = rotation % 360.0;
        return result < 0 ? result + 360.0 : result;
    }
}   